using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using System.Windows.Media;
namespace FrameScout {
 public sealed class StableSplitter : Thumb {
  Grid grid;GridLength[] original;double[] start;int left,right;double anchor;bool resizing;
  public bool IsResizing {get{return resizing;}}
  public StableSplitter(){var body=new FrameworkElementFactory(typeof(Border));body.SetValue(Border.BackgroundProperty,Brushes.Transparent);Template=new ControlTemplate(typeof(Thumb)){VisualTree=body};HorizontalAlignment=HorizontalAlignment.Stretch;VerticalAlignment=VerticalAlignment.Stretch;Cursor=Cursors.SizeWE;Focusable=true;ToolTip="按住拖动调整两侧宽度";DragStarted+=(s,e)=>{BeginResize();anchor=Mouse.GetPosition(grid).X;};DragDelta+=(s,e)=>{if(resizing)ResizeBy(Mouse.GetPosition(grid).X-anchor);};DragCompleted+=(s,e)=>FinishResize(e.Canceled);}
  public static void Replace(Grid parent){foreach(var old in parent.Children.OfType<GridSplitter>().ToList()){int at=parent.Children.IndexOf(old);var splitter=new StableSplitter();Grid.SetColumn(splitter,Grid.GetColumn(old));Grid.SetRow(splitter,Grid.GetRow(old));Grid.SetRowSpan(splitter,Grid.GetRowSpan(old));parent.Children.Remove(old);parent.Children.Insert(at,splitter);}}
  public void BeginResize(){if(resizing)return;grid=Parent as Grid;if(grid==null)return;left=Grid.GetColumn(this)-1;right=left+2;if(left<0||right>=grid.ColumnDefinitions.Count)return;grid.UpdateLayout();original=grid.ColumnDefinitions.Select(x=>x.Width).ToArray();start=grid.ColumnDefinitions.Select(x=>x.ActualWidth).ToArray();resizing=true;for(int i=0;i<start.Length;i++)grid.ColumnDefinitions[i].Width=new GridLength(Math.Max(0,start[i]),GridUnitType.Pixel);InvalidateVisual();}
  public void ResizeBy(double distance){if(!resizing||double.IsNaN(distance)||double.IsInfinity(distance))return;var a=grid.ColumnDefinitions[left];var b=grid.ColumnDefinitions[right];double total=start[left]+start[right],min=Math.Max(a.MinWidth,total-b.MaxWidth),max=Math.Min(a.MaxWidth,total-b.MinWidth);if(max<min)return;double first=Math.Max(min,Math.Min(max,start[left]+distance));a.Width=new GridLength(first,GridUnitType.Pixel);b.Width=new GridLength(Math.Max(0,total-first),GridUnitType.Pixel);}
  public void FinishResize(bool canceled=false){if(!resizing)return;resizing=false;for(int i=0;i<original.Length;i++){if(canceled)grid.ColumnDefinitions[i].Width=original[i];else if(i%2==0)grid.ColumnDefinitions[i].Width=new GridLength(Math.Max(.1,grid.ColumnDefinitions[i].Width.Value),GridUnitType.Star);else grid.ColumnDefinitions[i].Width=original[i];}original=null;start=null;InvalidateVisual();}
  protected override void OnRender(DrawingContext dc){dc.DrawRectangle(Brushes.Transparent,null,new Rect(RenderSize));var brush=new SolidColorBrush(Color.FromRgb(IsMouseOver||resizing?(byte)73:(byte)63,IsMouseOver||resizing?(byte)187:(byte)79,IsMouseOver||resizing?(byte)167:(byte)102));dc.DrawRoundedRectangle(brush,null,new Rect(Math.Max(0,(ActualWidth-3)/2),0,Math.Min(3,ActualWidth),ActualHeight),1.5,1.5);}
  protected override void OnMouseEnter(MouseEventArgs e){base.OnMouseEnter(e);InvalidateVisual();}protected override void OnMouseLeave(MouseEventArgs e){base.OnMouseLeave(e);InvalidateVisual();}
  protected override void OnKeyDown(KeyEventArgs e){if(e.Key==Key.Left||e.Key==Key.Right){BeginResize();ResizeBy(e.Key==Key.Left?-10:10);FinishResize();e.Handled=true;}else if(e.Key==Key.Escape&&resizing){FinishResize(true);e.Handled=true;}base.OnKeyDown(e);}
 }
 public sealed partial class Shell {
  Window columnChooser;
  void ShowColumnChooser(){if(columnChooser!=null){columnChooser.Activate();return;}var dialog=FrameWindows.Dialog(Window,"显示 / 隐藏列",300,495);columnChooser=dialog;dialog.ShowInTaskbar=false;dialog.MinWidth=240;dialog.MinHeight=260;dialog.UseLayoutRounding=true;var grid=new Grid{Margin=new Thickness(14)};grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.Children.Add(new TextBlock{Text="勾选要显示的列，面板会保持打开。",FontSize=12,Foreground=new SolidColorBrush(Color.FromRgb(143,162,189)),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)});var list=new StackPanel();foreach(var column in videos.Columns.OrderBy(x=>x.DisplayIndex)){var c=column;var box=new CheckBox{Content=c.Header,IsChecked=c.Visibility==Visibility.Visible,Tag=c,Margin=new Thickness(3,5,3,5)};RoutedEventHandler change=(s,e)=>{c.Visibility=box.IsChecked==true?Visibility.Visible:Visibility.Collapsed;QueueSave();};box.Checked+=change;box.Unchecked+=change;list.Children.Add(box);}var scroll=new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);grid.Children.Add(scroll);var close=new Button{Content="完成",HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};close.Click+=(s,e)=>dialog.Close();Grid.SetRow(close,2);grid.Children.Add(close);dialog.Content=grid;dialog.Closed+=(s,e)=>columnChooser=null;dialog.Show();}
 }
}
